import{_ as e,o as l,c as d,a2 as a}from"./chunks/framework.CZGNF-7T.js";const y=JSON.parse('{"title":"수수료 지급 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/payout.md","filePath":"sales/payout.md","lastUpdated":1788793693000}'),r={name:"sales/payout.md"};function n(i,t,s,o,g,c){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="수수료-지급-관리" tabindex="-1">수수료 지급 관리 <a class="header-anchor" href="#수수료-지급-관리" aria-label="Permalink to &quot;수수료 지급 관리&quot;">​</a></h1><p>확정된 정산 내역을 바탕으로 금융 이체 승인, 기업 인터넷 뱅킹 대량 이체 파일(CSV) 다운로드, 지급 완료 및 보류 처리를 일괄/개별 관리하는 페이지입니다.</p><ul><li><strong>위치</strong>: <code>PJT 관리 시스템 &gt; 분양 대행 관리 &gt; 수수료 지급 관리</code></li></ul><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>정산이 확정된 수수료에 대해 자금 집행을 총괄하는 화면입니다. 전체 실지급액과 현재까지의 이체 완료액 및 진척률을 실시간으로 모니터링하고, 다음 달 10일 세무 신고를 위한 **원천세 예수금 합계(3.3%)**를 사전에 파악할 수 있습니다. 또한 기업 뱅킹 사이트에 업로드할 수 있는 대량 이체용 CSV 파일을 생성 및 다운로드하고, 이체 완료 상태를 일괄 처리할 수 있습니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>지급 진행 현황 대시보드 (<code>PayoutStatusSummary</code>)</strong>: <ul><li>총 실지급 대상액 (세후) 및 대상 인원수</li><li>지급 완료액 및 이체 완료율 (%)</li><li>지급 잔액 (대기 및 보류 금액)</li><li>익월 10일 세무서 및 구청 신고 납부 대상 <strong>원천세 예수금 합계 (3.3%)</strong></li></ul></li><li><strong>회차 및 상태별 필터링</strong>: 정산 회차 선택, 지급 상태(지급대기/승인/완료/보류) 필터, 성명/계좌 키워드 검색</li><li><strong>다중 선택 기반 일괄 상태 변경</strong>: 체크박스로 여러 명을 선택하여 <code>[선택 승인]</code>, <code>[선택 지급완료]</code>, <code>[선택 지급보류]</code> 원클릭 처리</li><li><strong>기업 인터넷 뱅킹 대량 이체용 CSV 다운로드</strong>: <ul><li><code>UTF-8 BOM</code>(<code>\\uFEFF</code>) 인코딩 적용으로 엑셀 열람 시 한글 깨짐 원천 방지</li><li>긴 계좌번호 지수 표기(예: <code>1.23E+11</code>) 방지 탭 서식 적용</li><li>선택 항목 또는 현재 조회 목록 전체 다운로드 지원</li></ul></li><li><strong>개별 상태 변경 드롭다운</strong>: 행별로 지급 상태를 즉시 변경 가능하며, <code>지급완료</code> 선택 시 지급일자 자동 기록</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><h3 id="_1-회차-선택-및-필터-툴바" tabindex="-1">1. 회차 선택 및 필터 툴바 <a class="header-anchor" href="#_1-회차-선택-및-필터-툴바" aria-label="Permalink to &quot;1. 회차 선택 및 필터 툴바&quot;">​</a></h3><ul><li><strong>정산 회차 선택</strong>: 지급을 진행할 정산 회차 선택</li><li><strong>지급 상태 필터</strong>: 전체 상태, 지급대기(1), 지급승인(2), 지급완료(3), 지급보류(4)</li><li><strong>통합 검색창</strong>: 성명, 소속 팀, 예금주, 계좌번호로 실시간 필터링</li><li><strong>조회 건수 표출</strong>: 필터 조건에 해당하는 인원수 표시</li></ul><h3 id="_2-지급-진행-현황-대시보드-요약-카드" tabindex="-1">2. 지급 진행 현황 대시보드 (요약 카드) <a class="header-anchor" href="#_2-지급-진행-현황-대시보드-요약-카드" aria-label="Permalink to &quot;2. 지급 진행 현황 대시보드 (요약 카드)&quot;">​</a></h3><ul><li><strong>총 실지급 대상액 (세후)</strong>: 이번 회차에 집행되어야 할 총 이체 대상 금액</li><li><strong>지급 완료액 (이체완료)</strong>: 이미 지급 완료 처리된 금액과 전체 대비 진척률(%)</li><li><strong>지급 잔액 (대기/보류)</strong>: 아직 이체되지 않고 남아있는 잔액과 대기 인원수</li><li><strong>원천세 예수금 합계 (3.3%)</strong>: 회사가 원천징수하여 익월 10일에 국세청(소득세 3%) 및 지자체(지방소득세 0.3%)에 납부해야 할 세액 총액</li></ul><h3 id="_3-일괄-작업-및-이체-파일-다운로드-액션-바" tabindex="-1">3. 일괄 작업 및 이체 파일 다운로드 액션 바 <a class="header-anchor" href="#_3-일괄-작업-및-이체-파일-다운로드-액션-바" aria-label="Permalink to &quot;3. 일괄 작업 및 이체 파일 다운로드 액션 바&quot;">​</a></h3><ul><li><strong>전체 선택 체크박스</strong>: 현재 필터링된 모든 항목을 일괄 선택 또는 해제</li><li><strong>선택 정보 뱃지</strong>: 현재 선택된 인원수와 실지급 합계 금액 실시간 계산</li><li><strong>일괄 변경 버튼군</strong>: <ul><li><code>[선택 승인]</code>: 선택된 인력들의 상태를 <code>지급승인</code>으로 일괄 변경</li><li><code>[선택 지급완료]</code>: 선택된 인력들의 상태를 <code>지급완료</code>로 변경하고 오늘 일자를 지급일로 자동 기록</li><li><code>[선택 지급보류]</code>: 특이사항이나 계좌 오류 등으로 이체를 보류할 때 일괄 지정</li><li><code>[선택 해제]</code>: 선택 상태 초기화</li></ul></li><li><strong>[은행 이체용 CSV 다운로드] 버튼</strong>: 기업 뱅킹 이체 표준 규격에 맞춘 CSV 파일 다운로드</li></ul><h3 id="_4-지급-명세-테이블" tabindex="-1">4. 지급 명세 테이블 <a class="header-anchor" href="#_4-지급-명세-테이블" aria-label="Permalink to &quot;4. 지급 명세 테이블&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>선택 체크박스</strong></td><td style="text-align:left;">일괄 상태 변경 또는 선별 이체 다운로드를 위한 체크박스</td></tr><tr><td style="text-align:left;"><strong>소속 팀 / 직책 / 성명</strong></td><td style="text-align:left;">영업 인력의 인적 정보</td></tr><tr><td style="text-align:left;"><strong>은행명 / 계좌번호 / 예금주</strong></td><td style="text-align:left;">수수료가 입금될 금융 계좌 정보</td></tr><tr><td style="text-align:left;"><strong>총액 (세전)</strong></td><td style="text-align:left;">정산된 세전 총액</td></tr><tr><td style="text-align:left;"><strong>원천세 (3.3%)</strong></td><td style="text-align:left;">공제되는 원천징수 세액</td></tr><tr><td style="text-align:left;"><strong>실지급액 (세후)</strong></td><td style="text-align:left;">통장에 실제 입금될 금액 (테이블 강조 표시)</td></tr><tr><td style="text-align:left;"><strong>지급 상태</strong></td><td style="text-align:left;">드롭다운 셀렉터로 즉시 상태 변경 가능 (<code>지급대기</code>, <code>지급승인</code>, <code>지급완료</code>, <code>지급보류</code>)</td></tr><tr><td style="text-align:left;"><strong>상세</strong></td><td style="text-align:left;"><code>[내역]</code> 버튼 클릭 시 개인별 상세 계약 내역 모달 팝업</td></tr></tbody></table><h3 id="_5-은행-이체용-csv-파일-규격-안내" tabindex="-1">5. 은행 이체용 CSV 파일 규격 안내 <a class="header-anchor" href="#_5-은행-이체용-csv-파일-규격-안내" aria-label="Permalink to &quot;5. 은행 이체용 CSV 파일 규격 안내&quot;">​</a></h3><p>다운로드되는 CSV 파일은 기업 뱅킹 대량 이체 업로드 및 회계 전표 연동에 최적화되어 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:center;">열 순번</th><th style="text-align:left;">항목명</th><th style="text-align:left;">설명 및 포맷</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;">순번</td><td style="text-align:left;">1부터 시작하는 일련번호</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">입금은행</td><td style="text-align:left;">예: 국민은행, 신한은행</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">입금계좌번호</td><td style="text-align:left;">하이픈 포함 계좌번호 (지수 변환 방지 탭 문자 포함)</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">예금주</td><td style="text-align:left;">수취인 예금주명</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;">실지급액(세후)</td><td style="text-align:left;">순수 이체 대상 금액 (숫자)</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;">세전총액</td><td style="text-align:left;">원천세 공제 전 총액</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;">원천세(3.3%)</td><td style="text-align:left;">공제 세액 합계</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;">성명</td><td style="text-align:left;">영업 인력 성명</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;">소속팀</td><td style="text-align:left;">영업 본부/팀명</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;">직책</td><td style="text-align:left;">상담사, 팀장, 본부장 등</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;">지급상태</td><td style="text-align:left;">지급완료, 지급승인 등</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;">지급일자</td><td style="text-align:left;">YYYY-MM-DD 포맷</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;">정산회차</td><td style="text-align:left;">회차 명칭</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;">비고/메모</td><td style="text-align:left;">특이사항</td></tr></tbody></table>',19)])])}const f=e(r,[["render",n]]);export{y as __pageData,f as default};
